        "name": "src/main/java/dev/axziom/features/Feature.java",
        "source": "package dev.axziom.features;\n\nimport dev.axziom.features.settings.Setting;\nimport dev.axziom.features.settings.SettingFactory;\nimport dev.axziom.util.traits.Util;\n\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class Feature\n        implements Util, SettingFactory {\n    public List<Setting<?>> settings = new ArrayList<>();\n    private String name;\n\n    public Feature() {\n    }\n\n    public Feature(String name) {\n        this.name = name;\n    }\n\n    public static boolean nullCheck() {\n        return Feature.mc.player == null || Feature.mc.level == null;\n    }\n\n    public String getName() {\n        return this.name;\n    }\n\n    public List<Setting<?>> getSettings() {\n        return this.settings;\n    }\n\n    public boolean hasSettings() {\n        return !this.settings.isEmpty();\n    }\n\n    public boolean isEnabled() {\n        return false;\n    }\n\n    public boolean isDisabled() {\n        return !this.isEnabled();\n    }\n\n    public <T extends Setting<?>> T register(T setting) {\n        setting.setFeature(this);\n        this.settings.add(setting);\n        return setting;\n    }\n\n    public Setting<?> getSettingByName(String name) {\n        for (Setting<?> setting : this.settings) {\n            if (!setting.getName().equalsIgnoreCase(name)) continue;\n            return setting;\n        }\n        return null;\n    }\n\n    public void reset() {\n        for (Setting<?> setting : this.settings) {\n            setting.reset();\n        }\n    }\n}",
