      {
        "name": "src/main/java/dev/axziom/features/modules/client/TargetsModule.java",
        "source": "package dev.axziom.features.modules.client;\n\nimport dev.axziom.JewDust;\nimport dev.axziom.features.modules.Module;\nimport dev.axziom.features.settings.Setting;\nimport net.minecraft.world.entity.Entity;\nimport net.minecraft.world.entity.LivingEntity;\nimport net.minecraft.world.entity.Mob;\nimport net.minecraft.world.entity.animal.bee.Bee;\nimport net.minecraft.world.entity.animal.goat.Goat;\nimport net.minecraft.world.entity.animal.golem.IronGolem;\nimport net.minecraft.world.entity.animal.polarbear.PolarBear;\nimport net.minecraft.world.entity.animal.wolf.Wolf;\nimport net.minecraft.world.entity.boss.enderdragon.EnderDragon;\nimport net.minecraft.world.entity.monster.*;\nimport net.minecraft.world.entity.monster.piglin.Piglin;\nimport net.minecraft.world.entity.monster.spider.CaveSpider;\nimport net.minecraft.world.entity.monster.spider.Spider;\nimport net.minecraft.world.entity.monster.zombie.*;\nimport net.minecraft.world.entity.player.Player;\n\npublic class TargetsModule extends Module {\n\n    public final Setting<Boolean> players = bool(\"Players\", true);\n    public final Setting<Boolean> hostiles = bool(\"Hostiles\", false);\n    public final Setting<Boolean> neutrals = bool(\"Neutrals\", false);\n    public final Setting<Boolean> passives = bool(\"Passives\", false);\n\n    public TargetsModule() {\n        super(\"Targets\", \"Configure which entities combat modules target.\", Category.CLIENT);\n    }\n\n    @Override\n    public void onLoad() {\n        if (!isEnabled()) enable();\n    }\n\n    @Override\n    public void onDisable() {\n        enable();\n    }\n\n    public boolean isValidPlayerTarget(Entity entity) {\n        if (!(entity instanceof Player)) return false;\n        return isValidTarget(entity);\n    }\n\n    public boolean isValidTarget(Entity entity) {\n        if (entity == mc.player) return false;\n        if (!(entity instanceof LivingEntity living)) return false;\n        if (living.isDeadOrDying()) return false;\n\n        if (entity instanceof Player player) {\n            return players.getValue() && !JewDust.friendManager.isFriend(player);\n        }\n\n        if (hostiles.getValue() && isHostile(entity)) return true;\n        if (neutrals.getValue() && isNeutral(entity)) return true;\n        if (passives.getValue() && isPassive(entity)) return true;\n\n        return false;\n    }\n\n    public static boolean isHostile(Entity e) {\n        if (isNeutralEntityType(e)) return isAggressiveNow(e);\n        return e instanceof Enemy || e instanceof EnderDragon;\n    }\n\n    public static boolean isNeutral(Entity e) {\n        return isNeutralEntityType(e) && !isAggressiveNow(e);\n    }\n\n    public static boolean isPassive(Entity e) {\n        return e instanceof Mob && !isHostile(e) && !isNeutral(e);\n    }\n\n    private static boolean isNeutralEntityType(Entity e) {\n        return e instanceof EnderMan\n                || e instanceof Piglin\n                || e instanceof ZombifiedPiglin\n                || e instanceof Spider\n                || e instanceof CaveSpider\n                || e instanceof PolarBear\n                || (e instanceof Wolf w && !w.isTame())\n                || e instanceof Bee\n                || e instanceof Goat\n                || (e instanceof IronGolem g && !g.isPlayerCreated());\n    }\n\n    private static boolean isAggressiveNow(Entity e) {\n        if (e instanceof EnderMan enderman) return enderman.isCreepy();\n        if (e instanceof ZombifiedPiglin piglin) return piglin.isAggressive();\n        if (e instanceof Piglin piglin) return piglin.isAggressive();\n        if (e instanceof Spider spider) return spider.isAggressive();\n        if (e instanceof CaveSpider) return true;\n        if (e instanceof PolarBear bear) return bear.isAggressive();\n        if (e instanceof Wolf wolf) return wolf.isAggressive();\n        if (e instanceof Bee bee) return bee.isAngry();\n        return false;\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/features/modules/hud/ArmorHudModule.java",
        "source": "package dev.axziom.features.modules.hud;\n\nimport dev.axziom.event.impl.render.Render2DEvent;\nimport dev.axziom.features.modules.client.HudModule;\nimport dev.axziom.util.EnchantmentUtil;\nimport net.minecraft.client.gui.GuiGraphics;\nimport net.minecraft.resources.ResourceKey;\nimport net.minecraft.tags.FluidTags;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.enchantment.Enchantment;\nimport net.minecraft.world.item.enchantment.Enchantments;\n\npublic class ArmorHudModule extends HudModule {\n    private static final int ICON = 16;\n    private static final int STRIDE = 18;\n    private static final int HOTBAR_HALF = 91;\n    private static final int HUNGER_TOP_OFFSET = 39;\n    private static final int BUBBLE_HEIGHT = 10;\n    private static final float TAG_SCALE = 0.8f;\n\n    private static final EquipmentSlot[] SLOTS = {\n            EquipmentSlot.HEAD, EquipmentSlot.CHEST, EquipmentSlot.LEGS, EquipmentSlot.FEET\n    };\n\n    private record ProtTag(ResourceKey<Enchantment> key, String label) {}\n\n    private static final ProtTag[] PROT_TAGS = {\n            new ProtTag(Enchantments.PROTECTION, \"P\"),\n            new ProtTag(Enchantments.BLAST_PROTECTION, \"BP\"),\n            new ProtTag(Enchantments.FIRE_PROTECTION, \"FP\"),\n            new ProtTag(Enchantments.PROJECTILE_PROTECTION, \"PP\"),\n    };\n\n    public ArmorHudModule() {\n        super(\"Armor\");\n    }\n\n    @Override\n    public void render(Render2DEvent event) {\n        int totalWidth = SLOTS.length * STRIDE - (STRIDE - ICON);\n        int rightX = screenWidth() / 2 + HOTBAR_HALF;\n        int x = rightX - totalWidth;\n        int y = screenHeight() - HUNGER_TOP_OFFSET - 1 - ICON;\n        if (showingBubbles()) y -= BUBBLE_HEIGHT;\n\n        GuiGraphics ctx = event.getContext();\n        for (int i = 0; i < SLOTS.length; i++) {\n            int sx = x + i * STRIDE;\n            ItemStack stack = mc.player.getItemBySlot(SLOTS[i]);\n            if (stack.isEmpty()) continue;\n\n            ctx.renderItem(stack, sx, y);\n            ctx.renderItemDecorations(mc.font, stack, sx, y);\n\n            String tag = protectionTag(stack);\n            if (tag != null) {\n\n                ctx.pose().pushMatrix();\n                ctx.pose().scale(TAG_SCALE, TAG_SCALE);\n                ctx.drawString(mc.font, tag,\n                        Math.round(sx / TAG_SCALE), Math.round(y / TAG_SCALE),\n                        0xFFFFFFFF, true);\n                ctx.pose().popMatrix();\n            }\n        }\n    }\n\n    private String protectionTag(ItemStack stack) {\n        for (ProtTag t : PROT_TAGS) {\n            if (EnchantmentUtil.has(t.key(), stack)) return t.label();\n        }\n        return null;\n    }\n\n    private boolean showingBubbles() {\n        return mc.player.isEyeInFluid(FluidTags.WATER)\n                || mc.player.getAirSupply() < mc.player.getMaxAirSupply();\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/features/modules/hud/CountsHudModule.java",
        "source": "package dev.axziom.features.modules.hud;\n\nimport dev.axziom.event.impl.render.Render2DEvent;\nimport dev.axziom.features.modules.client.HudModule;\nimport net.minecraft.client.gui.GuiGraphics;\nimport net.minecraft.tags.FluidTags;\nimport net.minecraft.world.entity.player.Inventory;\nimport net.minecraft.world.item.Item;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.Items;\n\npublic class CountsHudModule extends HudModule {\n    private static final int ICON = 16;\n    private static final float ICON_SCALE = 0.85f;\n    private static final float RENDER_ICON = ICON * ICON_SCALE;\n    private static final int HOTBAR_HALF = 91;\n    private static final int HUNGER_TOP_OFFSET = 39;\n    private static final int BUBBLE_HEIGHT = 10;\n    private static final int GAP = 2;\n    private static final int TEXT_PAD = 2;\n    private static final int COLUMNS = 2;\n    private static final int ROW_HEIGHT = Math.round(RENDER_ICON);\n    private static final int CELL_WIDTH = 42;\n\n    private static final Item[] ITEMS = {\n            Items.END_CRYSTAL,\n            Items.OBSIDIAN,\n            Items.ENDER_PEARL,\n            Items.EXPERIENCE_BOTTLE,\n            Items.RESPAWN_ANCHOR,\n            Items.GLOWSTONE,\n            Items.PISTON,\n            Items.REDSTONE_BLOCK\n    };\n\n    public CountsHudModule() {\n        super(\"Counts\");\n    }\n\n    @Override\n    public void render(Render2DEvent event) {\n        GuiGraphics ctx = event.getContext();\n\n        int xLeft = screenWidth() / 2 + HOTBAR_HALF + GAP;\n        int yTop = screenHeight() - HUNGER_TOP_OFFSET - 1 - ICON;\n        if (showingBubbles()) yTop -= BUBBLE_HEIGHT;\n\n        for (int i = 0; i < ITEMS.length; i++) {\n            int column = i % COLUMNS;\n            int row = i / COLUMNS;\n            int x = xLeft + column * CELL_WIDTH;\n            int y = yTop + row * ROW_HEIGHT;\n            int count = countItem(ITEMS[i]);\n\n            ItemStack stack = new ItemStack(ITEMS[i], Math.max(count, 1));\n            drawIcon(ctx, stack, x, y);\n            drawCount(ctx, count, x, y);\n        }\n    }\n\n    private void drawIcon(GuiGraphics ctx, ItemStack stack, int x, int y) {\n\n        ctx.pose().pushMatrix();\n        ctx.pose().scale(ICON_SCALE, ICON_SCALE);\n        ctx.renderItem(stack, Math.round(x / ICON_SCALE), Math.round(y / ICON_SCALE));\n        ctx.pose().popMatrix();\n    }\n\n    private static final int GLYPH_HEIGHT = 8;\n\n    private void drawCount(GuiGraphics ctx, int count, int x, int y) {\n\n        String label = String.valueOf(count);\n        int drawX = Math.round(x + RENDER_ICON + TEXT_PAD);\n        int drawY = Math.round(y + (RENDER_ICON - GLYPH_HEIGHT) / 2f);\n        ctx.drawString(mc.font, label, drawX, drawY,\n                count > 0 ? 0xFFFFFFFF : 0xFFFF5555, true);\n    }\n\n    private int countItem(Item item) {\n        int total = 0;\n        Inventory inv = mc.player.getInventory();\n        for (int i = 0; i < inv.getContainerSize(); i++) {\n            ItemStack s = inv.getItem(i);\n            if (s.is(item)) total += s.getCount();\n        }\n        return total;\n    }\n\n    private boolean showingBubbles() {\n        return mc.player.isEyeInFluid(FluidTags.WATER)\n                || mc.player.getAirSupply() < mc.player.getMaxAirSupply();\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/features/modules/player/ReplenishModule.java",
        "source": "package dev.axziom.features.modules.player;\n\nimport dev.axziom.event.impl.entity.player.TickEvent;\nimport dev.axziom.event.system.Subscribe;\nimport dev.axziom.features.modules.Module;\nimport dev.axziom.features.settings.Setting;\nimport dev.axziom.util.inventory.InventoryUtil;\nimport net.minecraft.world.inventory.ClickType;\nimport net.minecraft.world.item.Item;\nimport net.minecraft.world.item.ItemStack;\n\nimport java.util.HashMap;\nimport java.util.Map;\n\npublic class ReplenishModule extends Module {\n\n    private final Setting<Integer> percentage = num(\"Percentage\", 20, 10, 50);\n    private final Setting<Boolean> alternative = bool(\"Alternative\", false);\n\n    private final Map<Integer, Integer> hotbarTicks = new HashMap<>();\n    private final Map<Integer, Item> lastHotbarItems = new HashMap<>();\n\n    public ReplenishModule() {\n        super(\"Replenish\", \"Automatically refills items in the hotbar.\", Category.MISC);\n    }\n\n    @Subscribe\n    private void onTick(TickEvent event) {\n        if (nullCheck()) return;\n        if (mc.screen != null) return;\n\n        if (!InventoryUtil.cursor().isEmpty()) return;\n\n        for (int hotbarSlot = 0; hotbarSlot < 9; hotbarSlot++) {\n            ItemStack stack = mc.player.getInventory().getItem(hotbarSlot);\n            Item currentItem = stack.isEmpty() ? null : stack.getItem();\n\n            if (lastHotbarItems.getOrDefault(hotbarSlot, null) != currentItem) {\n                hotbarTicks.put(hotbarSlot, 0);\n                lastHotbarItems.put(hotbarSlot, currentItem);\n            } else {\n                hotbarTicks.put(hotbarSlot, hotbarTicks.getOrDefault(hotbarSlot, 0) + 1);\n            }\n\n            if (hotbarTicks.getOrDefault(hotbarSlot, 0) < 10) continue;\n            if (stack.isEmpty()) continue;\n\n            int maxCount = stack.getMaxStackSize();\n            int minCount = Math.max(1, (int) (maxCount * (percentage.getValue() / 100f)));\n\n            if (stack.getCount() < minCount) {\n                int invSlot = findInventorySlotToReplenish(stack);\n                if (invSlot != -1) {\n                    swap(hotbarSlot, invSlot);\n                    return;\n                }\n            }\n        }\n    }\n\n    private int findInventorySlotToReplenish(ItemStack target) {\n        for (int i = 9; i < 36; i++) {\n            ItemStack stack = mc.player.getInventory().getItem(i);\n            if (stack.isEmpty()) continue;\n\n            if (!ItemStack.isSameItemSameComponents(stack, target)) continue;\n            return i;\n        }\n        return -1;\n    }\n\n    private void swap(int hotbarSlot, int invSlot) {\n\n        int realInvSlot = invSlot;\n        int realHotbarSlot = hotbarSlot + 36;\n\n        if (alternative.getValue()) {\n\n            InventoryUtil.click(realInvSlot, 0, ClickType.QUICK_MOVE);\n        } else {\n\n            InventoryUtil.click(realInvSlot, 0, ClickType.PICKUP);\n            InventoryUtil.click(realHotbarSlot, 0, ClickType.PICKUP);\n            InventoryUtil.click(realInvSlot, 0, ClickType.PICKUP);\n        }\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/features/settings/EnumConverter.java",
        "source": "package dev.axziom.features.settings;\n\nimport com.google.common.base.Converter;\nimport com.google.gson.JsonElement;\nimport com.google.gson.JsonPrimitive;\n\n@SuppressWarnings(\"unchecked\")\npublic class EnumConverter<T extends Enum<T>> extends Converter<T, JsonElement> {\n    private final Class<T> clazz;\n\n    public EnumConverter(Class<T> clazz) {\n        this.clazz = clazz;\n    }\n\n    public static <T extends Enum<?>> int currentEnum(T clazz) {\n        for (int i = 0; i < clazz.getDeclaringClass().getEnumConstants().length; ++i) {\n            T e = (T) clazz.getDeclaringClass().getEnumConstants()[i];\n            if (!e.name().equalsIgnoreCase(clazz.name())) continue;\n            return i;\n        }\n        return -1;\n    }\n\n    public static <T extends Enum<?>> T increaseEnum(T clazz) {\n        int index = EnumConverter.currentEnum(clazz);\n        for (int i = 0; i < clazz.getDeclaringClass().getEnumConstants().length; ++i) {\n            T e = (T) clazz.getDeclaringClass().getEnumConstants()[i];\n            if (i != index + 1) continue;\n            return e;\n        }\n        return (T) clazz.getDeclaringClass().getEnumConstants()[0];\n    }\n\n    public static <T extends Enum<?>> String getProperName(T clazz) {\n        String[] parts = clazz.name().toLowerCase().split(\"_\");\n        StringBuilder sb = new StringBuilder();\n        for (String part : parts) {\n            if (part.isEmpty()) continue;\n            if (sb.length() > 0) sb.append(' ');\n            sb.append(Character.toUpperCase(part.charAt(0))).append(part.substring(1));\n        }\n        return sb.toString();\n    }\n\n    public JsonElement doForward(Enum anEnum) {\n        return new JsonPrimitive(anEnum.toString());\n    }\n\n    public T doBackward(JsonElement jsonElement) {\n        try {\n            return Enum.valueOf(this.clazz, jsonElement.getAsString());\n        } catch (IllegalArgumentException e) {\n            return null;\n        }\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/manager/EnemyManager.java",
        "source": "package dev.axziom.manager;\n\nimport com.google.gson.JsonArray;\nimport com.google.gson.JsonElement;\nimport com.google.gson.JsonObject;\nimport dev.axziom.JewDust;\nimport dev.axziom.util.traits.Jsonable;\nimport net.minecraft.world.entity.player.Player;\n\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class EnemyManager implements Jsonable {\n    private final List<String> enemies = new ArrayList<>();\n\n    public void init() {\n        JewDust.configManager.addConfig(this);\n    }\n\n    public boolean isEnemy(String name) {\n        return this.enemies.stream().anyMatch(enemy -> enemy.equalsIgnoreCase(name));\n    }\n\n    public boolean isEnemy(Player player) {\n        return this.isEnemy(player.getGameProfile().name());\n    }\n\n    public void addEnemy(String name) {\n        this.enemies.add(name);\n\n        JewDust.friendManager.removeFriend(name);\n    }\n\n    public void removeEnemy(String name) {\n        enemies.removeIf(s -> s.equalsIgnoreCase(name));\n    }\n\n    public void clearEnemies() {\n        enemies.clear();\n    }\n\n    public List<String> getEnemies() {\n        return this.enemies;\n    }\n\n    @Override\n    public JsonElement toJson() {\n        JsonObject object = new JsonObject();\n        JsonArray array = new JsonArray();\n        for (String enemy : enemies) {\n            array.add(enemy);\n        }\n        object.add(\"enemies\", array);\n        return object;\n    }\n\n    @Override\n    public void fromJson(JsonElement element) {\n        for (JsonElement e : element.getAsJsonObject().get(\"enemies\").getAsJsonArray()) {\n            enemies.add(e.getAsString());\n        }\n    }\n\n    @Override\n    public String getFileName() {\n        return \"enemies.json\";\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/manager/EventManager.java",
        "source": "package dev.axziom.manager;\n\nimport dev.axziom.JewDust;\nimport dev.axziom.event.Stage;\nimport dev.axziom.event.impl.entity.DeathEvent;\nimport dev.axziom.event.impl.entity.player.TickEvent;\nimport dev.axziom.event.impl.entity.player.UpdateWalkingPlayerEvent;\nimport dev.axziom.event.impl.input.KeyInputEvent;\nimport dev.axziom.event.impl.input.MouseInputEvent;\nimport dev.axziom.event.impl.network.ChatEvent;\nimport dev.axziom.event.impl.render.Render2DEvent;\nimport dev.axziom.event.impl.render.Render3DEvent;\nimport dev.axziom.event.system.Subscribe;\nimport dev.axziom.features.Feature;\nimport net.minecraft.world.entity.player.Player;\n\npublic class EventManager extends Feature {\n    public void init() {\n        EVENT_BUS.register(this);\n    }\n\n    public void onUnload() {\n        EVENT_BUS.unregister(this);\n    }\n\n    @Subscribe\n    public void onTick(TickEvent event) {\n        if (nullCheck())\n            return;\n        JewDust.moduleManager.onTick();\n        for (Player player : mc.level.players()) {\n            if (player == null || player.getHealth() > 0.0F)\n                continue;\n            EVENT_BUS.post(new DeathEvent(player));\n        }\n    }\n\n    @Subscribe(priority = 100)\n    public void onUpdateWalkingPlayer(UpdateWalkingPlayerEvent event) {\n        if (nullCheck())\n            return;\n        if (event.getStage() == Stage.PRE) {\n            JewDust.positionManager.updatePosition();\n        }\n        if (event.getStage() == Stage.POST) {\n            JewDust.positionManager.restorePosition();\n        }\n    }\n\n    @Subscribe\n    public void onWorldRender(Render3DEvent event) {\n        JewDust.moduleManager.onRender3D(event);\n    }\n\n    @Subscribe\n    public void onRenderGameOverlayEvent(Render2DEvent event) {\n        JewDust.moduleManager.onRender2D(event);\n    }\n\n    @Subscribe\n    public void onKeyInput(KeyInputEvent event) {\n        if (event.getAction() == 1) {\n            JewDust.moduleManager.onKeyPressed(event.getKey());\n        } else if (event.getAction() == 0) {\n            JewDust.moduleManager.onKeyReleased(event.getKey());\n        }\n    }\n\n    @Subscribe\n    public void onMouseInput(MouseInputEvent event) {\n        if (event.getAction() == 1) {\n            JewDust.moduleManager.onMousePressed(event.getButton());\n        } else if (event.getAction() == 0) {\n            JewDust.moduleManager.onMouseReleased(event.getButton());\n        }\n    }\n\n    @Subscribe\n    public void onChatSent(ChatEvent event) {\n        String message = event.getMessage();\n        if (!message.startsWith(JewDust.commandManager.getCommandPrefix())) {\n            return;\n        }\n        event.cancel();\n        JewDust.commandManager.onChatSent(message);\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/manager/PlayerInfoManager.java",
        "source": "package dev.axziom.manager;\n\nimport dev.axziom.event.impl.entity.TotemPopEvent;\nimport dev.axziom.event.impl.entity.player.PreTickEvent;\nimport dev.axziom.event.impl.network.DisconnectEvent;\nimport dev.axziom.event.system.Subscribe;\nimport dev.axziom.features.Feature;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraft.world.entity.player.Player;\nimport net.minecraft.world.item.ItemStack;\n\nimport java.util.HashSet;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.UUID;\nimport java.util.concurrent.ConcurrentHashMap;\n\npublic class PlayerInfoManager extends Feature {\n\n    private final Map<UUID, Integer> totemPops = new ConcurrentHashMap<>();\n    private final Set<UUID> lastTickAlive = ConcurrentHashMap.newKeySet();\n\n    public void init() {\n        EVENT_BUS.register(this);\n    }\n\n    @Subscribe\n    public void onTotemPop(TotemPopEvent event) {\n        totemPops.merge(event.getEntity().getUUID(), 1, Integer::sum);\n    }\n\n    @Subscribe\n    public void onPreTick(PreTickEvent event) {\n        if (mc.level == null || mc.player == null) return;\n\n        Set<UUID> currentlyAlive = new HashSet<>();\n        Set<UUID> presentIds = new HashSet<>();\n        for (Player player : mc.level.players()) {\n            UUID id = player.getUUID();\n            presentIds.add(id);\n            if (player.isDeadOrDying()) {\n                if (lastTickAlive.contains(id)) {\n                    totemPops.remove(id);\n                }\n            } else {\n                currentlyAlive.add(id);\n            }\n        }\n\n        totemPops.keySet().removeIf(id -> !presentIds.contains(id));\n        lastTickAlive.clear();\n        lastTickAlive.addAll(currentlyAlive);\n    }\n\n    @Subscribe\n    public void onDisconnect(DisconnectEvent event) {\n        resetAll();\n    }\n\n    public int getTotemPops(UUID uuid) {\n        return totemPops.getOrDefault(uuid, 0);\n    }\n\n    public void resetTotemPops(UUID uuid) {\n        totemPops.remove(uuid);\n    }\n\n    public void resetAll() {\n        totemPops.clear();\n        lastTickAlive.clear();\n    }\n\n    public ItemStack getEquipment(Player player, EquipmentSlot slot) {\n        return player.getItemBySlot(slot);\n    }\n\n    public ItemStack getMainHandItem(Player player) {\n        return player.getMainHandItem();\n    }\n\n    public ItemStack getOffHandItem(Player player) {\n        return player.getOffhandItem();\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/manager/TPSCounterService.java",
        "source": "package dev.axziom.manager;\n\nimport dev.axziom.event.impl.network.DisconnectEvent;\nimport dev.axziom.event.impl.network.PacketEvent;\nimport dev.axziom.event.system.Subscribe;\nimport dev.axziom.features.Feature;\nimport net.minecraft.network.protocol.game.ClientboundSetTimePacket;\n\npublic class TPSCounterService extends Feature {\n    private final float[] tickRates = new float[20];\n    private int nextIndex = 0;\n    private int countTick = 0;\n    private long lastTimeUpdate = -1;\n\n    public void init() {\n        EVENT_BUS.register(this);\n    }\n\n    @Subscribe\n    public void onDisconnect(DisconnectEvent event) {\n        nextIndex = 0;\n        countTick = 0;\n        lastTimeUpdate = -1;\n    }\n\n    @Subscribe\n    public void onPacketReceive(PacketEvent.Receive event) {\n        if (!(event.getPacket() instanceof ClientboundSetTimePacket)) return;\n\n        long now = System.currentTimeMillis();\n\n        if (lastTimeUpdate != -1) {\n            float elapsed = (now - lastTimeUpdate) / 1000.0f;\n            float tps = 20.0f / elapsed;\n            tickRates[nextIndex % tickRates.length] = Math.min(Math.max(tps, 0.0f), 20.0f);\n            nextIndex++;\n            countTick = Math.min(countTick + 1, tickRates.length);\n        }\n\n        lastTimeUpdate = now;\n    }\n\n    public float getAverageTPS() {\n        if (countTick == 0) return 20.0f;\n\n        float sum = 0.0f;\n        int valid = 0;\n        for (int i = 0; i < countTick; i++) {\n            float t = tickRates[i];\n            if (t > 0.0f) {\n                sum += t;\n                valid++;\n            }\n        }\n        return valid == 0 ? 20.0f : Math.min(Math.max(sum / valid, 0.0f), 20.0f);\n    }\n\n    public float getLatestTPS() {\n        if (countTick == 0) return 20.0f;\n\n        int last = (nextIndex - 1 + tickRates.length) % tickRates.length;\n        return Math.min(Math.max(tickRates[last], 0.0f), 20.0f);\n    }\n\n    public float getMinTPS() {\n        if (countTick == 0) return 20.0f;\n\n        float min = 20.0f;\n        for (int i = 0; i < countTick; i++) {\n            float t = tickRates[i];\n            if (t > 0.0f && t < min) {\n                min = t;\n            }\n        }\n        return Math.min(Math.max(min, 0.0f), 20.0f);\n    }\n}",
        "repo": "BlackieHackie"
      },
      {
        "name": "src/main/java/dev/axziom/mixin/entity/MixinLocalPlayerRotation.java",
        "source": "package dev.axziom.mixin.entity;\n\nimport dev.axziom.JewDust;\nimport dev.axziom.features.modules.movement.RocketBoost;\nimport dev.axziom.features.modules.movement.YawLockModule;\nimport dev.axziom.manager.RotationManager;\nimport net.minecraft.client.player.LocalPlayer;\nimport org.spongepowered.asm.mixin.Mixin;\nimport org.spongepowered.asm.mixin.Shadow;\nimport org.spongepowered.asm.mixin.Unique;\nimport org.spongepowered.asm.mixin.injection.At;\nimport org.spongepowered.asm.mixin.injection.Inject;\nimport org.spongepowered.asm.mixin.injection.callback.CallbackInfo;\n\n@Mixin(value = LocalPlayer.class, priority = Integer.MAX_VALUE)\npublic class MixinLocalPlayerRotation {\n    @Shadow private float xRotLast;\n\n    @Unique private float jewdust$savedYaw;\n    @Unique private float jewdust$savedPitch;\n    @Unique private boolean jewdust$spoofed;\n\n    @Inject(method = \"sendPosition\", at = @At(\"HEAD\"))\n    private void jewdust$spoofRotationHead(CallbackInfo ci) {\n        jewdust$spoofed = false;\n        LocalPlayer player = (LocalPlayer) (Object) this;\n        RotationManager rotation = JewDust.rotationManager;\n\n        boolean motionRotation = rotation != null && rotation.isRotating();\n        boolean managerSilent = rotation != null && rotation.isSilentSyncRequired();\n        boolean viewSilent = false;\n\n        jewdust$savedYaw = player.getYRot();\n        jewdust$savedPitch = player.getXRot();\n        float outputYaw = jewdust$savedYaw;\n        float outputPitch = jewdust$savedPitch;\n\n        // Existing combat rotations keep priority over camera utility modules.\n        if (motionRotation) {\n            outputYaw = rotation.getRotationYaw();\n            outputPitch = rotation.getRotationPitch();\n        } else if (managerSilent) {\n            // The old code restored the client rotation here, undoing every\n            // silent request. Send the manager's actual server rotation instead.\n            outputYaw = rotation.getServerYaw();\n            outputPitch = rotation.getServerPitch();\n        } else if (JewDust.moduleManager != null) {\n            RocketBoost rocketBoost = JewDust.moduleManager.getModuleByClass(RocketBoost.class);\n            if (rocketBoost != null && rocketBoost.hasSilentPitchOverride()) {\n                outputYaw = rocketBoost.getControlledYaw();\n                outputPitch = rocketBoost.getControlledPitch();\n                viewSilent = true;\n            }\n\n            YawLockModule yawLock = JewDust.moduleManager.getModuleByClass(YawLockModule.class);\n            if (yawLock != null && yawLock.hasSilentServerYaw()) {\n                outputYaw = yawLock.getLockedYaw();\n                viewSilent = true;\n            }\n            if (yawLock != null && yawLock.hasSilentServerPitch()) {\n                outputPitch = yawLock.getLockedPitch();\n                viewSilent = true;\n            }\n        }\n\n        if (!motionRotation && !managerSilent && !viewSilent) return;\n\n        // Force sendPosition to include rotation even when the locked angle has\n        // not changed since the previous movement packet.\n        xRotLast -= 4.0f;\n        player.setYRot(outputYaw);\n        player.setXRot(outputPitch);\n        jewdust$spoofed = true;\n\n        if (rotation != null) {\n            rotation.setServerDeltaYaw(outputYaw - rotation.getServerYaw());\n            rotation.setServerYaw(outputYaw);\n            rotation.setServerPitch(outputPitch);\n        }\n    }\n\n    @Inject(method = \"sendPosition\", at = @At(\"TAIL\"))\n    private void jewdust$spoofRotationTail(CallbackInfo ci) {\n        LocalPlayer player = (LocalPlayer) (Object) this;\n        if (jewdust$spoofed) {\n            player.setYRot(jewdust$savedYaw);\n            player.setXRot(jewdust$savedPitch);\n            jewdust$spoofed = false;\n        }\n\n        RotationManager rotation = JewDust.rotationManager;\n        if (rotation != null) {\n            rotation.setSilentSyncRequired(false);\n            rotation.resetSilentTick();\n        }\n    }\n}",
        "repo": "BlackieHackie"
      }
