        "source": "// ipxnet.c\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <dos.h>\n#include <string.h>\n#include <process.h>\n#include <values.h>\n\n#include \"ipxnet.h\"\n\n/*\n==========================================================================\n===\n\n                              IPX PACKET DRIVER\n\n==========================================================================\n===\n*/\n\npacket_t        packets[NUMPACKETS];\n\nnodeadr_t      nodeadr[MAXNETNODES+1];  // first is local, last is broadcast",
