        "name": "sdl_main.c:162",
        "source": "scc(SDL_Init(SDL_INIT_VIDEO));\n    scc(TTF_Init());\n    window = scp(SDL_CreateWindow(\n                     \"Snake Native SDL\",\n                     0, 0,\n                     WIDTH, HEIGHT,\n                     SDL_WINDOW_RESIZABLE));\n\n    renderer = scp(SDL_CreateRenderer(\n                       window,\n                       -1,\n                       SDL_RENDERER_ACCELERATED));\n\n    scc(SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND));\n\n    bool quit = false;\n    while (!quit) {\n        SDL_Event event;\n        while (SDL_PollEvent(&event)) {\n            switch (event.type) {\n            case SDL_QUIT: {\n                quit = true;\n            }\n            break;\n\n            case SDL_KEYDOWN: {\n                game_keydown(event.key.keysym.sym);\n            }\n            break;\n\n            case SDL_WINDOWEVENT: {\n                switch (event.window.event) {\n                case SDL_WINDOWEVENT_RESIZED: {\n                    game_resize(event.window.data1, event.window.data2);\n                }\n                break;\n                }\n            } break;\n            }\n        }\n\n        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 0);\n        SDL_RenderClear(renderer);\n        game_update(1.0f/60.0f);\n        game_render();\n        // TODO: better way to lock 60 FPS\n        SDL_RenderPresent(renderer);\n        SDL_Delay(1000/60);\n    }\n\n    TTF_Quit();\n    SDL_Quit();\n\n    return 0;\n}",
